                        builder -> builder.operationId("UpdatePostContent")
                                .description("Update only the content of an existing post.")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .name("name")
                                        .description("metadata.name of the post whose content will be updated.")
