                                        .content(contentBuilder()
                                                .mediaType(MediaType.MULTIPART_FORM_DATA_VALUE)
                                                .schema(schemaBuilder().implementation(InstallRequest.class))))
                                .response(responseBuilder().implementation(Plugin.class)))
                .POST(
                        "plugins/-/install-from-uri",
                        this::installFromUri,
                        builder -> builder.operationId("InstallPluginFromUri")
                                .description("Install a plugin from uri.")
                                .tag(tag)
                                .requestBody(requestBodyBuilder()
                                        .required(true)
                                        .content(contentBuilder()
                                                .mediaType(MediaType.APPLICATION_JSON_VALUE)
                                                .schema(schemaBuilder().implementation(InstallFromUriRequest.class))))
                                .response(responseBuilder().implementation(Plugin.class)))
                .POST(
                        "plugins/{name}/upgrade-from-uri",
                        this::upgradeFromUri,
                        builder -> builder.operationId("UpgradePluginFromUri")
                                .description("Upgrade a plugin from uri.")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .in(ParameterIn.PATH)
                                        .name("name")
                                        .description("metadata.name of the plugin to upgrade.")
                                        .required(true))
                                .requestBody(requestBodyBuilder()
                                        .required(true)
                                        .content(contentBuilder()
                                                .mediaType(MediaType.APPLICATION_JSON_VALUE)
                                                .schema(schemaBuilder().implementation(UpgradeFromUriRequest.class))))
                                .response(responseBuilder().implementation(Plugin.class)))
                .POST(
                        "plugins/{name}/upgrade",
                        contentType(MediaType.MULTIPART_FORM_DATA),
                        this::upgrade,
                        builder -> builder.operationId("UpgradePlugin")
                                .description("Upgrade a plugin by uploading a Jar file")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .name("name")
                                        .description("metadata.name of the plugin to upgrade.")
                                        .in(ParameterIn.PATH)
                                        .required(true))
                                .requestBody(requestBodyBuilder()
