                                .response(responseBuilder()
                                        .responseCode(String.valueOf(HttpStatus.NO_CONTENT.value()))
                                        .implementation(Void.class)))
                .PUT(
                        "plugins/{name}/reset-config",
                        this::resetSettingConfig,
                        builder -> builder.operationId("ResetPluginConfig")
                                .description("Reset the configMap of plugin setting.")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .name("name")
                                        .description("metadata.name of the plugin whose setting config will be reset.")
                                        .in(ParameterIn.PATH)
                                        .required(true)
                                        .implementation(String.class))
                                .response(responseBuilder().implementation(ConfigMap.class)))
                .PUT(
                        "plugins/{name}/reload",
                        this::reload,
                        builder -> builder.operationId("reloadPlugin")
                                .description("Reload a plugin by metadata.name.")
                                .tag(tag)
                                .parameter(parameterBuilder()
                                        .name("name")
                                        .description("metadata.name of the plugin to reload.")
                                        .in(ParameterIn.PATH)
                                        .required(true)
                                        .implementation(String.class))
                                .response(responseBuilder().implementation(Plugin.class)))
                .PUT(
