                                .parameter(parameterBuilder()
                                        .name("name")
                                        .description("metadata.name of the plugin whose running state will be changed.")
                                        .in(ParameterIn.PATH)
                                        .required(true)
                                        .implementation(String.class))
                                .requestBody(requestBodyBuilder()
                                        .required(true)
